css.om:
:host {
  --bg: #ffffff;
  --panel: #f6f9fc;
  --fg: #111c2c;
  --fg-2: #516381;
  --fg-3: #8e9fbc;
  --line: #e3e8f2;
  --line-2: #ecf1f9;
  --accent: #0263e0;
  --accent-soft: rgba(2,99,224,0.08);
  --canvas-bg: #fdfdfe;
  --canvas-dot: #dfe6f0;
  --code-bg: #f1f5fa;
  --purple: #6d2ed1;
  --sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  --mono: "JetBrains Mono", "SFMono-Regular", ui-monospace, Menlo, monospace;
}
@media (prefers-color-scheme: dark) {
  :host {
    --bg: #07101f;
    --panel: #0c1729;
    --fg: #ecf1f9;
    --fg-2: #9dadc8;
    --fg-3: #66789a;
    --line: #1d2b45;
    --line-2: #16233a;
    --accent: #4cb1fe;
    --accent-soft: rgba(76,177,254,0.10);
    --canvas-bg: #fdfdfe;
    --canvas-dot: #dfe6f0;
    --code-bg: #101d33;
    --purple: #b78bf5;
  }
}
:host[data-theme="light"] {
  --bg: #ffffff; --panel: #f6f9fc; --fg: #111c2c; --fg-2: #516381; --fg-3: #8e9fbc;
  --line: #e3e8f2; --line-2: #ecf1f9; --accent: #0263e0; --accent-soft: rgba(2,99,224,0.08);
  --canvas-bg: #fdfdfe; --canvas-dot: #dfe6f0; --code-bg: #f1f5fa; --purple: #6d2ed1;
}
:host[data-theme="dark"] {
  --bg: #07101f; --panel: #0c1729; --fg: #ecf1f9; --fg-2: #9dadc8; --fg-3: #66789a;
  --line: #1d2b45; --line-2: #16233a; --accent: #4cb1fe; --accent-soft: rgba(76,177,254,0.10);
  --canvas-bg: #fdfdfe; --canvas-dot: #dfe6f0; --code-bg: #101d33; --purple: #b78bf5;
}

* { box-sizing: border-box; }
:host {
  margin: 0; background: var(--bg); color: var(--fg);
  font: 400 13px/1.55 var(--sans);
  -webkit-font-smoothing: antialiased;
}
a { color: var(--accent); text-decoration: none; }
a:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { display: flex; min-height: 100vh; }

/* ââ Rail ââ */
.rail {
  width: 240px; flex-shrink: 0; border-right: 1px solid var(--line);
  padding: 28px 16px 40px; position: sticky; top: 0; align-self: flex-start;
  max-height: 100vh; overflow-y: auto;
}
.rail .brand { padding: 0 10px 18px; border-bottom: 1px solid var(--line-2); margin-bottom: 14px; }
.rail .brand .t { font: 600 13px/1.35 var(--sans); letter-spacing: -0.01em; }
.rail .brand .s { font: 400 11px/1.5 var(--sans); color: var(--fg-3); margin-top: 2px; }
.rail .grp { font: 600 10px/1 var(--sans); letter-spacing: 0.08em; text-transform: uppercase; color: var(--fg-3); padding: 14px 10px 6px; }
.rail a.item {
  display: block; padding: 5px 10px; border-radius: 6px;
  font: 500 12px/1.5 var(--sans); color: var(--fg-2);
}
.rail a.item:hover { background: var(--panel); color: var(--fg); }

/* ââ Main column ââ */
.main { flex: 1; min-width: 0; padding: 40px 48px 96px; }
.main > * { max-width: 920px; }

header.hero { margin-bottom: 40px; }
header.hero .eyebrow { font: 600 10px/1 var(--sans); letter-spacing: 0.1em; text-transform: uppercase; color: var(--accent); margin-bottom: 10px; }
header.hero h1 { margin: 0 0 8px; font: 600 24px/1.25 var(--sans); letter-spacing: -0.02em; text-wrap: balance; }
header.hero p { margin: 0; color: var(--fg-2); max-width: 62ch; }
.stats { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.stats .stat {
  border: 1px solid var(--line); border-radius: 6px; padding: 6px 12px;
  font: 500 11px/1.5 var(--sans); color: var(--fg-2); background: var(--panel);
}
.stats .stat b { color: var(--fg); font-weight: 600; font-variant-numeric: tabular-nums; }

section.sec { margin-top: 56px; }
section.sec > h2 { font: 600 18px/1.3 var(--sans); letter-spacing: -0.015em; margin: 0 0 4px; padding-top: 8px; }
section.sec > .lede { color: var(--fg-2); margin: 0 0 20px; max-width: 68ch; }
h3.sub { font: 600 14px/1.35 var(--sans); margin: 32px 0 10px; }

/* Component block */
.comp { border: 1px solid var(--line); border-radius: 10px; margin: 18px 0; overflow: hidden; }
.comp .head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; padding: 14px 18px 0; }
.comp .head h4 { margin: 0; font: 600 14px/1.35 var(--sans); }
.comp .head .src { font: 400 11px/1.5 var(--mono); color: var(--fg-3); }
.badge {
  display: inline-flex; align-items: center; border-radius: 48px; padding: 1px 8px;
  font: 500 10px/1.6 var(--sans); white-space: nowrap;
}
.badge.atom { background: var(--accent-soft); color: var(--accent); }
.badge.inline { background: rgba(151,71,255,0.12); color: var(--purple); }
.comp .desc { padding: 4px 18px 0; color: var(--fg-2); font-size: 12px; max-width: 70ch; }
.comp .desc code, .note code, td code, .lede code { font: 400 11px/1.4 var(--mono); background: var(--code-bg); border-radius: 4px; padding: 1px 5px; }

/* Specimen canvas: always the product's light ground */
.canvas {
  margin: 14px 18px 18px; border: 1px solid var(--line); border-radius: 8px;
  background-color: var(--canvas-bg);
  background-image: radial-gradient(var(--canvas-dot) 1px, transparent 1px);
  background-size: 16px 16px;
  padding: 22px; display: flex; flex-wrap: wrap; gap: 14px; align-items: center;
  color: rgb(29,42,62); font-family: var(--sans);
}
.canvas.col { flex-direction: column; align-items: stretch; gap: 16px; }
.canvas .lbl { flex-basis: 100%; font: 600 10px/1 var(--sans); letter-spacing: 0.08em; text-transform: uppercase; color: #8e9fbc; }
.note { padding: 0 18px 14px; color: var(--fg-3); font-size: 11px; }
.note b { color: var(--fg-2); font-weight: 600; }

table.spec { border-collapse: collapse; width: 100%; font-size: 12px; }
.tablewrap { overflow-x: auto; margin: 12px 0; }
table.spec th { text-align: left; font: 600 11px/1.5 var(--sans); color: var(--fg-2); border-bottom: 1px solid var(--line); padding: 6px 10px; }
table.spec td { border-bottom: 1px solid var(--line-2); padding: 6px 10px; vertical-align: top; color: var(--fg-2); }
table.spec td:first-child { color: var(--fg); font-weight: 500; white-space: nowrap; }
table.spec td.mono, table.spec .mono { font: 400 11px/1.6 var(--mono); }

/* ââ Token swatches ââ */
.ramp { display: flex; flex-wrap: wrap; gap: 8px; margin: 10px 0 4px; }
.sw { width: 132px; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: var(--panel); }
.sw .c { height: 44px; border-bottom: 1px solid var(--line); }
.sw .n { font: 500 11px/1.4 var(--sans); padding: 6px 8px 0; }
.sw .v { font: 400 10px/1.4 var(--mono); color: var(--fg-3); padding: 0 8px 7px; }

/* type scale demo */
.type-row { display: flex; align-items: baseline; gap: 18px; padding: 10px 0; border-bottom: 1px solid var(--line-2); }
.type-row .meta { width: 190px; flex-shrink: 0; font: 400 11px/1.5 var(--mono); color: var(--fg-3); }
.type-row .demo { color: var(--fg); }

/* radius & shadow demos */
.rad-demo { display: flex; gap: 14px; flex-wrap: wrap; }
.rad-demo .r { width: 96px; height: 64px; background: var(--panel); border: 1px solid var(--line); display: flex; align-items: flex-end; padding: 8px; font: 400 10px/1.4 var(--mono); color: var(--fg-3); }
.shadow-demo { display: flex; gap: 18px; flex-wrap: wrap; }
.shadow-demo .s { width: 132px; height: 72px; background: #fff; border-radius: 8px; display: flex; align-items: flex-end; padding: 10px; font: 400 10px/1.4 var(--mono); color: #71727a; }

/* spacing demo */
.space-demo { display: flex; align-items: flex-end; gap: 14px; flex-wrap: wrap; }
.space-demo .sp { display: flex; flex-direction: column; align-items: center; gap: 6px; font: 400 10px/1.4 var(--mono); color: var(--fg-3); }
.space-demo .bar { width: 22px; background: var(--accent-soft); border: 1px solid var(--accent); border-radius: 2px; }

/* ââ Icon grid ââ */
.icon-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 8px; margin-top: 14px; }
.icon-cell {
  border: 1px solid var(--line); border-radius: 8px; padding: 12px 6px 9px;
  display: flex; flex-direction: column; align-items: center; gap: 7px; text-align: center;
  background: var(--panel);
}
.icon-cell svg { color: var(--fg); }
.icon-cell .nm { font: 500 10px/1.3 var(--mono); color: var(--fg-2); word-break: break-all; }
.icon-cell .ct { font: 400 9px/1 var(--sans); color: var(--fg-3); font-variant-numeric: tabular-nums; }
.icon-cell.dead { opacity: 0.45; }
.icon-cell.dead .ct { color: #b41226; }

/* âââââââââââ Motadata specimen styles (exact token values, light-only) âââââââââââ */
.m { font-family: var(--sans); }
.m-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 36px; padding: 0 14px; border-radius: 6px; border: 1px solid transparent;
  font: 500 12px/1 var(--sans); cursor: pointer; white-space: nowrap;
}
.m-btn.sm { height: 28px; padding: 0 10px; font-size: 11px; }
.m-btn.lg { height: 40px; padding: 0 16px; font-size: 13px; }
.m-btn.primary   { background: rgb(7,16,31); color: #fff; border-color: rgb(7,16,31); }
.m-btn.secondary { background: #fff; color: rgb(17,28,44); border-color: rgb(202,211,226); }
.m-btn.tertiary  { background: rgb(236,241,249); color: rgb(29,42,62); border-color: rgb(236,241,249); }
.m-btn.danger    { background: rgb(219,19,42); color: #fff; border-color: rgb(219,19,42); }
.m-btn.dangerGhost { background: #fff; color: rgb(219,19,42); border-color: rgba(219,19,42,0.30); }
.m-btn.warning   { background: rgb(180,114,4); color: #fff; border-color: rgb(180,114,4); }
.m-btn.ai        { background: rgb(245,240,252); color: rgb(109,46,209); border-color: rgba(151,71,255,0.18); }
.m-btn.ghost     { background: transparent; color: rgb(81,99,129); border-color: transparent; }
.m-btn.link      { background: transparent; color: rgb(2,99,224); border-color: transparent; }
.m-btn[disabled] { opacity: 0.45; cursor: not-allowed; }
.m-iconbtn {
  width: 28px; height: 28px; border-radius: 6px; background: transparent;
  border: 1px solid transparent; display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer; color: rgb(81,99,129);
}
.m-iconbtn:hover { background: rgb(246,249,252); border-color: rgb(227,232,242); }
.m-iconbtn.danger { color: rgb(219,19,42); }

.m-pill {
  display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px 2px 6px;
  border-radius: 48px; font: 500 11px/1.5 var(--sans); white-space: nowrap;
}
.m-pill .dot { width: 6px; height: 6px; border-radius: 99px; flex-shrink: 0; }

.m-chip {
  display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px;
  border-radius: 4px; font: 500 11px/1.5 var(--sans); border: 1px solid; white-space: nowrap;
}
.m-chip .x { display: inline-flex; padding: 1px; margin-left: 2px; opacity: 0.6; cursor: pointer; }

.m-avatar { border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-weight: 600; flex-shrink: 0; }
.m-tile { display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; }

.m-field { display: flex; flex-direction: column; gap: 6px; width: 240px; }
.m-field .lab { font: 500 12px/1.4 var(--sans); color: rgb(29,42,62); }
.m-field .lab .req { color: rgb(219,19,42); margin-left: 3px; }
.m-field .box {
  height: 36px; padding: 0 12px; border-radius: 6px; border: 1px solid rgb(202,211,226);
  background: #fff; display: flex; align-items: center; gap: 8px;
  font: 400 12px/1 var(--sans); color: rgb(17,28,44);
}
.m-field .box .ph { color: rgb(142,159,188); }
.m-field.error .box { border-color: rgb(234,67,53); }
.m-field.disabled .box { background: rgb(246,249,252); color: rgb(142,159,188); }
.m-field .hint { font: 400 11px/1.4 var(--sans); color: rgb(113,113,130); }
.m-field.error .hint { color: rgb(219,19,42); }

.m-switch { width: 32px; height: 18px; border-radius: 99px; padding: 2px; display: inline-flex; align-items: center; flex-shrink: 0; }
.m-switch .knob { width: 14px; height: 14px; border-radius: 99px; background: #fff; box-shadow: 0 1px 2px rgba(7,16,31,0.20); }
.m-switch.on { background: rgb(2,99,224); justify-content: flex-end; }
.m-switch.off { background: rgb(202,211,226); }

.m-check { width: 16px; height: 16px; border-radius: 4px; display: inline-flex; align-items: center; justify-content: center; color: #fff; flex-shrink: 0; }
.m-check.on { background: rgb(2,99,224); border: 1px solid rgb(2,99,224); }
.m-check.off { background: #fff; border: 1px solid rgb(202,211,226); }
.m-radio { width: 16px; height: 16px; border-radius: 99px; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; }
.m-radio.on { border: 1.5px solid rgb(2,99,224); }
.m-radio.on i { width: 8px; height: 8px; border-radius: 99px; background: rgb(2,99,224); }
.m-radio.off { border: 1.5px solid rgb(202,211,226); }
.ctl-row { display: inline-flex; align-items: center; gap: 8px; font: 400 12px/1.4 var(--sans); color: rgb(17,28,44); }

.m-card { background: #fff; border: 1px solid rgb(236,241,249); border-radius: 8px; padding: 20px; }
.m-banner { border-radius: 8px; padding: 10px 12px; display: flex; gap: 10px; align-items: flex-start; font: 400 12px/1.5 var(--sans); color: rgb(29,42,62); border: 1px solid; width: 100%; max-width: 460px; }
.m-banner .ico { margin-top: 2px; flex-shrink: 0; display: inline-flex; }
.m-banner b { display: block; font: 600 12px/1.5 var(--sans); color: rgb(17,28,44); margin-bottom: 2px; }

.m-menu { width: 200px; background: #fff; border: 1px solid rgb(227,232,242); border-radius: 8px; box-shadow: 0 8px 24px rgba(7,16,31,0.10), 0 2px 4px rgba(7,16,31,0.06); padding: 4px; font: 500 12px/1.35 var(--sans); }
.m-menu .it { padding: 8px 10px; border-radius: 6px; color: rgb(17,28,44); display: flex; align-items: center; gap: 8px; cursor: pointer; }
.m-menu .it svg { color: rgb(113,113,130); }
.m-menu .it:hover { background: rgb(246,249,252); }
.m-menu .it.danger { color: rgb(219,19,42); } .m-menu .it.danger svg { color: rgb(219,19,42); }
.m-menu .it.disabled { color: rgb(142,159,188); cursor: not-allowed; }
.m-menu .div { height: 1px; background: rgb(236,241,249); margin: 4px 0; }

.m-modal { width: 400px; max-width: 100%; background: #fff; border-radius: 12px; box-shadow: 0 24px 48px rgba(7,16,31,0.20); overflow: hidden; font-family: var(--sans); }
.m-modal .hd { padding: 20px 24px 16px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.m-modal .hd h5 { margin: 0; font: 600 16px/1.35 var(--sans); color: rgb(17,28,44); }
.m-modal .bd { padding: 0 24px 20px; font: 400 12px/1.5 var(--sans); color: rgb(29,42,62); }
.m-modal .ft { padding: 16px 24px; border-top: 1px solid rgb(236,241,249); background: rgb(246,249,252); display: flex; gap: 10px; justify-content: flex-end; }

.m-meter { width: 300px; }
.m-meter .track { position: relative; height: 6px; border-radius: 99px; background: rgb(236,241,249); }
.m-meter .fill { position: absolute; left: 0; top: 0; height: 100%; border-radius: 99px; background: rgb(2,99,224); }
.m-meter .base { position: absolute; top: -3px; width: 2px; height: 12px; background: rgb(151,71,255); border-radius: 99px; }
.m-meter .floor { position: absolute; top: -1px; width: 1px; height: 8px; background: rgb(142,159,188); }
.m-meter .ends { display: flex; justify-content: space-between; font: 400 10px/1 var(--sans); color: rgb(113,113,130); margin-top: 6px; }

@media (max-width: 860px) {
  .rail { display: none; }
  .main { padding: 28px 20px 72px; }
}
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }

